setup_shell:
mkdir -p .gymtool && rm -f .gymtool/_check.rs .gymtool/_check_bin && cat > .gymtool/solution.rs <<'RUSTEOF'
pub fn add(a: i32, b: i32) -> i32 {
    a - b // BUG: should add
}
RUSTEOF

dod_shell:
cat > .gymtool/_check.rs <<'RUSTEOF'
include!("solution.rs");
fn main() {
    assert_eq!(add(2, 3), 5);
    assert_eq!(add(-4, 4), 0);
    assert_eq!(add(100, 1), 101);
    println!("PASS");
}
RUSTEOF
rustc --edition 2021 -A warnings .gymtool/_check.rs -o .gymtool/_check_bin 2>&1 && .gymtool/_check_bin

